UIAimerGraphics=function(game,gameController){Phaser.Graphics.call(this,game,0,0);this.gameController=gameController;this.colour=0x00ff00;this.kill();};UIAimerGraphics.prototype=Object.create(Phaser.Graphics.prototype);UIAimerGraphics.prototype.constructor=UIAimerGraphics;UIAimerGraphics._multiplyAdd=function(a,b,s,out){if(out===undefined){out=new Phaser.Point();}return out.setTo(a.x+b.x*s,a.y+b.y*s);};UIAimerGraphics.prototype._castRay=function(start,end){var ray=new p2.Ray({mode:p2.Ray.CLOSEST,from:[-start.x,-start.y],to:[-end.x,-end.y],skipBackfaces:true,collisionMask:UIUtils.wallCollisionGroup.mask|UIUtils.tankCollisionGroup.mask|UIUtils.shieldCollisionGroup.mask|UIUtils.spawnCollisionGroup.mask,collisionGroup:UIUtils.rayCollisionGroup.mask});var result=new p2.RaycastResult();this.game.physics.p2.world.raycast(result,ray);var returnResult={};returnResult.hasHit=result.hasHit();if(result.hasHit()){var hitPoint=[0,0];result.getHitPoint(hitPoint,ray);returnResult.hitPoint=new Phaser.Point(-hitPoint[0],-hitPoint[1]);returnResult.hitNormal=new Phaser.Point(-result.normal[0],-result.normal[1]);returnResult.hitDistance=result.getHitDistance(ray);returnResult.hasHitTank=(result.shape.collisionGroup==UIUtils.tankCollisionGroup.mask);returnResult.hasHitSpawn=(result.shape.collisionGroup==UIUtils.spawnCollisionGroup.mask);}return returnResult;};UIAimerGraphics.prototype.spawn=function(playerId,maxLength,activated){this.revive();this.clear();this.playerId=playerId;this.maxLength=maxLength;this.activated=activated;var self=this;Backend.getInstance().getPlayerDetails(function(result){if(typeof(result)=="object"){self.colour=result.getTurretColour().numericValue;}else{self.colour=UIConstants.TANK_UNAVAILABLE_COLOUR.numericValue;}},function(result){},function(result){},this.playerId,Caches.getPlayerDetailsCache());};UIAimerGraphics.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}if(!this.activated){return;}var aimerPositions=[];var remainingLength=this.maxLength;var tank=this.gameController.getTank(this.playerId);if(tank){aimerPositions.push(new Phaser.Point(tank.getX()+Math.sin(tank.getRotation())*UIUtils.pxm(UIConstants.AIMER_OFFSET),tank.getY()-Math.cos(tank.getRotation())*UIUtils.pxm(UIConstants.AIMER_OFFSET)));var rayDir=new Phaser.Point(Math.sin(tank.getRotation()),-Math.cos(tank.getRotation()));var rayStart=new Phaser.Point(0,0);var rayEnd=new Phaser.Point(0,0);while(remainingLength>0.0){rayStart.x=aimerPositions[aimerPositions.length-1].x;rayStart.y=aimerPositions[aimerPositions.length-1].y;UIAimerGraphics._multiplyAdd(rayStart,rayDir,remainingLength,rayEnd);var result=this._castRay(rayStart,rayEnd);if(result.hasHit){aimerPositions.push(result.hitPoint);if(result.hasHitTank||result.hasHitSpawn){break;}else{remainingLength-=Math.max(UIConstants.AIMER_MIN_STEP_LENGTH,result.hitDistance);UIAimerGraphics._multiplyAdd(rayDir,result.hitNormal,-2*rayDir.dot(result.hitNormal),rayDir);rayDir.normalize();}}else{aimerPositions.push(rayEnd);break;}}}this.clear();this.lineStyle(UIConstants.AIMER_WIDTH,this.colour,1.0);var beamPosition=new Phaser.Point(0,0);var beamOn=Math.random()>0.5;var segmentSample=0.0;if(aimerPositions.length>=2){var minSegmentLength=QualityManager.getQualityValue(QualityManager.QUALITY_PARAMETERS.AIMER_MIN_SEGMENT_LENGTH);var maxOffSegmentLength=QualityManager.getQualityValue(QualityManager.QUALITY_PARAMETERS.AIMER_OFF_MAX_SEGMENT_LENGTH);var maxOnSegmentLength=QualityManager.getQualityValue(QualityManager.QUALITY_PARAMETERS.AIMER_ON_MAX_SEGMENT_LENGTH);this.moveTo(UIUtils.mpx(aimerPositions[0].x),UIUtils.mpx(aimerPositions[0].y));for(var i=1;i<aimerPositions.length;++i){var segmentStart=aimerPositions[i-1];var segmentEnd=aimerPositions[i];var segmentDir=Phaser.Point.subtract(segmentEnd,segmentStart);var segmentLength=segmentDir.getMagnitude();segmentDir.normalize();while(segmentSample<segmentLength){UIAimerGraphics._multiplyAdd(segmentStart,segmentDir,segmentSample,beamPosition);if(beamOn){this.lineTo(UIUtils.mpx(beamPosition.x),UIUtils.mpx(beamPosition.y));segmentSample+=minSegmentLength+Math.random()*(maxOffSegmentLength-minSegmentLength);}else{this.moveTo(UIUtils.mpx(beamPosition.x),UIUtils.mpx(beamPosition.y));segmentSample+=minSegmentLength+Math.random()*(maxOnSegmentLength-minSegmentLength);}beamOn=!beamOn;}segmentSample-=segmentLength;}}};UIAimerGraphics.prototype.getPlayerId=function(){return this.playerId;};UIAimerGraphics.prototype.activate=function(){this.activated=true;};UIAimerGraphics.prototype.weaken=function(){};UIAimerGraphics.prototype.strengthen=function(){};UIAimerGraphics.prototype.remove=function(){this.kill();};UIAimerGraphics.prototype.retire=function(){this.kill();};